        throw new IllegalArgumentException("Size must be non-negative");
    }
    int neededCapacity = this.data.length + size;
    if (neededCapacity > this.data.length) {
        int newCapacity = Math.max(this.data.length << 1, neededCapacity);
        byte[] newData = new byte[newCapacity];
