public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    try {
        for (int i = 0; i < actualTypeArguments.length; i++) {
            if (actualTypeArguments[i] instanceof Class) {
                resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
            } else if (actualTypeArguments[i] instanceof TypeVariable) {
                resolvedArguments[i] = resolveTypeVariable((TypeVariable<?>) actualTypeArguments[i], targetType);
            } else {
                return null; // Cannot resolve this type
            }
        }
    } catch (Exception e) {
        return null; // In case of any exceptions, return null
    }

    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length != 1 || !(bounds[0] instanceof Class)) {
        return null; // Cannot resolve if bounds are not a single class
    }

    Class<?>[] typeParameters = ((Class<?>) bounds[0]).getTypeParameters();
    if (typeParameters.length != targetType.getTypeParameters().length) {
        return null; // Mismatch in the number of type parameters
    }

    Type superClass = targetType.getGenericSuperclass();
    if (superClass instanceof ParameterizedType) {
        ParameterizedType parameterizedSuperClass = (ParameterizedType) superClass;
        Type[] actualTypeArguments = parameterizedSuperClass.getActualTypeArguments();
        for (int i = 0; i < actualTypeArguments.length; i++) {
            if (actualTypeArguments[i] instanceof Class && typeParameters[i].equals(typeVariable)) {
                return (Class<?>) actualTypeArguments[i];
            }
        }
    }

    return null; // Could not resolve the type variable
}

