static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);
        int day = monthDay % 100;
        int month = monthDay / 100;

        // Calculate the start day of the month
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            daysInMonth[1] = 29; // Leap year
        }

        int startDayOfMonth = 1;
        int endDayOfMonth = daysInMonth[month - 1];

        // Find the closest dayStep aligned day
        int alignedDay = ((day - 1) / dayStep) * dayStep + 1;
        if (alignedDay < startDayOfMonth) {
            alignedDay = startDayOfMonth;
        } else if (alignedDay > endDayOfMonth) {
            alignedDay = endDayOfMonth;
        }

        return year * 10000 + month * 100 + alignedDay;
    } catch (Exception e) {
        // Handle unexpected errors, return the original timeBucket
        return timeBucket;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        char ch = str.charAt(i++);
        if (ch < 0x80) {
            size++;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            int cp = ch;
            if (i < end) {
                char ch2 = str.charAt(i);
                if (Character.isSurrogatePair(ch, ch2)) {
                    cp = Character.toCodePoint(ch, ch2);
                    i++;
                }
            }
            if (cp < 0x10000) {
                size += 3;
            } else {
                size += 4;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

