public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        int length = str.length();
        int bytesLen = 0;
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                bytesLen++;
            } else if (c <= 0x7FF) {
                bytesLen += 2;
            } else if (Character.isHighSurrogate(c) && i + 1 < length && Character.isLowSurrogate(str.charAt(i + 1))) {
                bytesLen += 4;
                i++;
            } else {
                bytesLen += 3;
            }
        }

        lb = ensureRoom(5 + bytesLen, session, lb);
        int start = lb.start;

        // Write the length as a varint
        lb = writeVarInt32(bytesLen, session, lb);

        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                lb.buffer[start++] = (byte) c;
            } else if (c <= 0x7FF) {
                lb.buffer[start++] = (byte) (0xC0 | (c >> 6));
                lb.buffer[start++] = (byte) (0x80 | (c & 0x3F));
            } else if (Character.isHighSurrogate(c) && i + 1 < length && Character.isLowSurrogate(str.charAt(i + 1))) {
                int high = c;
                int low = str.charAt(i + 1);
                int uc = Character.toCodePoint(high, low);
                lb.buffer[start++] = (byte) (0xF0 | (uc >> 18));
                lb.buffer[start++] = (byte) (0x80 | ((uc >> 12) & 0x3F));
                lb.buffer[start++] = (byte) (0x80 | ((uc >> 6) & 0x3F));
                lb.buffer[start++] = (byte) (0x80 | (uc & 0x3F));
                i++;
            } else {
                lb.buffer[start++] = (byte) (0xE0 | (c >> 12));
                lb.buffer[start++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                lb.buffer[start++] = (byte) (0x80 | (c & 0x3F));
            }
        }

        lb.start = start;
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF8 string to LinkedBuffer", e);
    }
}

