private static String substituteVariables(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int variableStart = value.indexOf("${");
    int variableEnd;

    while (variableStart != -1) {
        result.append(value, 0, variableStart);
        variableEnd = value.indexOf("}", variableStart);

        if (variableEnd != -1) {
            String variableKey = value.substring(variableStart + 2, variableEnd);
            String variableValue = substituteVariables(props.getProperty(variableKey, ""), props);
            result.append(variableValue);
            value = value.substring(variableEnd + 1);
            variableStart = value.indexOf("${");
        } else {
            break;
        }
    }
    result.append(value);
    return result.toString();
}

