private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    if (descriptor.startsWith("(")) {
        // It's a method descriptor, extract argument types
        int endParenthesesIndex = descriptor.indexOf(')');
        if (endParenthesesIndex == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing closing parenthesis");
        }
        String argumentTypes = descriptor.substring(1, endParenthesesIndex);
        int index = 0;
        while (index < argumentTypes.length()) {
            char type = argumentTypes.charAt(index);
            switch (type) {
                case 'B':
                case 'C':
                case 'I':
                case 'S':
                case 'Z':
                case 'F':
                    // Pop one slot
                    index++;
                    break;
                case 'D':
                case 'J':
                    // Pop two slots
                    index += 2;
                    break;
                case 'L':
                    // Object type, pop one slot
                    index = argumentTypes.indexOf(';', index) + 1;
                    if (index == 0) {
                        throw new IllegalArgumentException("Invalid method descriptor: missing semicolon in object type");
                    }
                    break;
                case '[':
                    // Array type, pop one slot
                    index++;
                    while (index < argumentTypes.length() && argumentTypes.charAt(index) == '[') {
                        index++;
                    }
                    if (index < argumentTypes.length() && argumentTypes.charAt(index) == 'L') {
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid method descriptor: missing semicolon in array object type");
                        }
                    } else {
                        index++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid method descriptor: unknown type " + type);
            }
        }
    } else {
        // It's a type descriptor, pop based on type
        char type = descriptor.charAt(0);
        switch (type) {
            case 'B':
            case 'C':
            case 'I':
            case 'S':
            case 'Z':
            case 'F':
                // Pop one slot
                break;
            case 'D':
            case 'J':
                // Pop two slots
                break;
            case 'L':
                // Object type, pop one slot
                if (descriptor.indexOf(';') == -1) {
                    throw new IllegalArgumentException("Invalid type descriptor: missing semicolon in object type");
                }
                break;
            case '[':
                // Array type, pop one slot
                break;
            default:
                throw new IllegalArgumentException("Invalid type descriptor: unknown type " + type);
        }
    }
}

