String function ( String str ) throws Exception {
    if ( str == null ) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    int length = str.length();
    for ( int i = 0; i < length; i++ ) {
        char currentChar = str.charAt( i );
        if ( currentChar == '\\' ) {
            if ( i + 1 < length ) {
                char nextChar = str.charAt( i + 1 );
                switch ( nextChar ) {
                    case 'b':
                        output.append( '\b' );
                        break;
                    case 't':
                        output.append( '\t' );
                        break;
                    case 'n':
                        output.append( '\n' );
                        break;
                    case 'f':
                        output.append( '\f' );
                        break;
                    case 'r':
                        output.append( '\r' );
                        break;
                    case '\"':
                        output.append( '"' );
                        break;
                    case '\'':
                        output.append( '\'' );
                        break;
                    case '\\':
                        output.append( '\\' );
                        break;
                    default:
                        throw new Exception( "Invalid escape sequence: \\" + nextChar );
                }
                i++; // Skip the next character as it is already processed
            } else {
                throw new Exception( "Trailing backslash" );
            }
        } else {
            output.append( currentChar );
        }
    }
    return output.toString();
}

