private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    if (descriptor.charAt(0) == '(') { // It's a method descriptor
        int i = 1;
        while (descriptor.charAt(i) != ')') {
            i = consumeType(descriptor, i);
        }
    } else {
        consumeType(descriptor, 0);
    }
}

private int consumeType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'I': case 'S': case 'Z':
        case 'F': case 'D': case 'J':
            index++;
            break;
        case 'L':
            index = descriptor.indexOf(';', index) + 1;
            if (index == 0) {
                throw new IllegalArgumentException("Invalid object type descriptor: " + descriptor);
            }
            break;
        case '[':
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            if (index == descriptor.length()) {
                throw new IllegalArgumentException("Invalid array type descriptor: " + descriptor);
            }
            index = consumeType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

