public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    String normalizedPath = path.endsWith("/") ? path : path + "/";
    String[] pathParts = normalizedPath.split("/");
    String[] relativePathParts = relativePath.split("/");

    for (String part : relativePathParts) {
        if (part.equals("..")) {
            if (pathParts.length > 1) {
                pathParts = Arrays.copyOf(pathParts, pathParts.length - 1);
            }
        } else if (part.equals(".")) {
            // Current directory, do nothing
        } else if (!part.isEmpty()) {
            List<String> pathList = new ArrayList<>(Arrays.asList(pathParts));
            pathList.add(part);
            pathParts = pathList.toArray(new String[0]);
        }
    }

    return String.join("/", pathParts);
}

